const item = $input.first().json;

// Extract real sender email from Gmail metadata strictly (never body)
let rawFrom = item.from || '';
let fromEmail = '';
if (typeof rawFrom === 'object' && rawFrom.address) {
  fromEmail = rawFrom.address;
} else if (typeof rawFrom === 'string') {
  const match = rawFrom.match(/<([^>]+)>/);
  fromEmail = match ? match[1] : rawFrom;
}
fromEmail = fromEmail.trim().toLowerCase();

const subject = item.subject || 'No Subject';
const bodyText = item.text || item.snippet || item.body || '';
const messageId = item.id || item.messageId || `msg_${Date.now()}`;
const threadId = item.threadId || messageId;

return [{
  json: {
    fromEmail,
    subject,
    bodyText,
    messageId,
    threadId,
    rawFrom
  }
}];

const meta = $('Extract Email Metadata').item.json;
const profile = $('Lookup Profile by Email').item.json;
const holdersRecords = $input.all();

const authorizedAccounts = [];
holdersRecords.forEach(rec => {
  if (rec.json && rec.json.accounts) {
    authorizedAccounts.push({
      account_id: rec.json.accounts.id,
      account_number: rec.json.accounts.account_number,
      account_type: rec.json.accounts.account_type,
      currency: rec.json.accounts.currency,
      balance: rec.json.accounts.balance,
      status: rec.json.accounts.status,
      role: rec.json.role
    });
  }
});

const subject = meta.subject.toLowerCase();
const body = meta.bodyText.toLowerCase();
const text = subject + ' ' + body;

let intent = 'UNKNOWN';
let transferDetails = null;

// 1. Balance Inquiry
if (text.includes('balance') || text.includes('how much') || text.includes('statement') || text.includes('summary')) {
  intent = 'BALANCE';
}
// 2. Transfer Request
else if (text.includes('transfer') || text.includes('send') || text.includes('pay') || text.includes('pkr') || text.includes('usd') || text.includes('dollars') || text.includes('rupees')) {
  intent = 'TRANSFER';

  // Extract amount
  let amountCents = 0;
  const amountMatch = text.match(/(?:send|transfer|pay)?\s*\$?([0-9]+(?:\.[0-9]{1,2})?)\s*(?:pkr|usd|dollars|rupees|cents)?/i);
  if (amountMatch) {
    const num = parseFloat(amountMatch[1]);
    if (!isNaN(num)) {
      amountCents = Math.round(num < 10000 && !text.includes('cents') ? num * 100 : num);
    }
  }
  if (amountCents === 0) amountCents = 10000;

  // Extract target account number or UUID if present
  let destAccount = null;
  const accountMatch = meta.bodyText.match(/TEST-[A-Z0-9-]+|[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/i);
  if (accountMatch) {
    destAccount = accountMatch[0];
  }

  const primaryAcc = authorizedAccounts.find(a => a.role === 'primary' && a.status === 'active') || authorizedAccounts[0];

  transferDetails = {
    source_account_id: primaryAcc ? primaryAcc.account_id : null,
    destination_account: destAccount,
    amount: amountCents,
    currency: primaryAcc ? primaryAcc.currency : 'USD',
    idempotency_key: `gmail_${meta.messageId}`
  };
}
// 3. Policy / RAG Query
else if (text.includes('policy') || text.includes('fee') || text.includes('limit') || text.includes('wire') || text.includes('overdraft') || text.includes('credit card') || text.includes('rule') || text.includes('support') || text.includes('help')) {
  intent = 'POLICY_RAG';
}
// 4. Standing Orders
else if (text.includes('standing order') || text.includes('recurring') || text.includes('schedule')) {
  intent = 'STANDING_ORDER';
}
// 5. Dispute / Fraud Alert
else if (text.includes('dispute') || text.includes('fraud') || text.includes('unauthorized') || text.includes('stolen') || text.includes('freeze')) {
  intent = 'DISPUTE';
}

// 6. Security & Privacy check: Check if user asks for third-party profile balance
if (text.includes('customer b') || (text.includes('bob') && profile.email.includes('alice'))) {
  intent = 'UNAUTHORIZED_ACCESS';
}

return [{
  json: {
    fromEmail: meta.fromEmail,
    subject: meta.subject,
    bodyText: meta.bodyText,
    messageId: meta.messageId,
    profile_id: profile.id,
    full_name: profile.full_name,
    authorizedAccounts,
    intent,
    transferDetails
  }
}];

const item = $input.first().json;
const accounts = item.authorizedAccounts || [];

let balanceMsg = `Hello ${item.full_name},

Here is your authorized account balance summary:

`;

if (accounts.length === 0) {
  balanceMsg += "No active accounts found for your profile.";
} else {
  accounts.forEach(acc => {
    const formatted = (acc.balance / 100).toFixed(2);
    balanceMsg += `- Account ${acc.account_number} (${acc.account_type.toUpperCase()}, Role: ${acc.role}): $${formatted} ${acc.currency} (Status: ${acc.status})
`;
  });
}

balanceMsg += `
Thank you for banking with Digital Bank.`;

return [{ json: { fromEmail: item.fromEmail, subject: item.subject, message: balanceMsg, profile_id: item.profile_id } }];

